public protocol MurmurProtocol: AnyObject, Sendable {
    
    func deleteMeeting(id: String) throws 
    
    func deleteVoice() throws 
    
    /**
     * Throws the recording away: nothing is saved, and its audio and photos are deleted.
     */
    func discard() throws 
    
    /**
     * Makes and saves the print from the user reading the sentence. Fails (translated) with too
     * little speech, to read it again.
     */
    func enrollVoice(samples: [Float]) throws  -> Double
    
    /**
     * Whether a recording is in progress (after the app was killed, it isn't).
     */
    func isRecording()  -> Bool
    
    /**
     * A meeting as the computer stores it (JSON), or None.
     */
    func meetingJson(id: String) throws  -> String?
    
    /**
     * The meetings, newest first.
     */
    func meetings() throws  -> [MeetingRow]
    
    /**
     * Every line of `from` is `into`'s: two speakers that were the same person.
     */
    func mergeSpeakers(id: String, from: Int64, into: Int64) throws 
    
    /**
     * Loads the models now (they load on the first recording otherwise): about half a second.
     */
    func prepare() throws 
    
    /**
     * 16 kHz mono samples from the microphone.
     */
    func push(samples: [Float]) throws  -> LiveUpdate
    
    /**
     * Saves a whole meeting as the computer stores it (JSON): the sample meetings of the App
     * Store's screenshots (`-demo`, development only).
     */
    func putMeeting(json: String) throws 
    
    /**
     * A new title for a meeting (empty: left as it was).
     */
    func renameMeeting(id: String, title: String) throws 
    
    /**
     * Searches titles, transcripts and notes (every word, as the beginning of a word: the
     * computer's search).
     */
    func search(query: String) throws  -> [SearchHit]
    
    /**
     * One line goes to another speaker, set by hand (`speakerLocked`: the computer's final pass
     * leaves it alone).
     */
    func setLineSpeaker(id: String, line: String, speaker: Int64) throws 
    
    /**
     * The notes of a finished meeting, as the computer's editor stores them (a TipTap document).
     */
    func setNotes(id: String, doc: String) throws 
    
    /**
     * A speaker's name ("Parlant 2" is "Laia"); empty takes it away. As the computer stores it:
     * `speakerNames` by number.
     */
    func setSpeakerName(id: String, speaker: Int64, name: String) throws 
    
    /**
     * A meeting's tags (by client, project…), the same as the computer's.
     */
    func setTags(id: String, tags: [String]) throws 
    
    /**
     * A task of the cover done (or not), by its place in the list.
     */
    func setTaskDone(id: String, task: UInt32, done: Bool) throws 
    
    /**
     * Starts recording a meeting: `title` as the phone shows it until the computer names it,
     * `language` ("ca", "es", "ca-es", "en"), whether there are more people in the room (or
     * it's only the user: one speaker), and how often the provisional text is redone (0: never).
     * Returns the meeting's id.
     */
    func start(title: String, language: String, moreInRoom: Bool, partialEvery: Float) throws  -> String
    
    /**
     * Stops and saves the meeting. `extra` is a JSON object the app adds to it: its notes
     * (`notesDoc`), its photos (`screens`) and the moments marked as important (`marks`).
     */
    func stop(extra: String) throws  -> String
    
    /**
     * How many words of `sentence` have been read so far in `samples` (the karaoke).
     */
    func voiceProgress(sentence: String, samples: [Float]) throws  -> UInt32
    
    /**
     * When it was saved (seconds since 1970), if it is.
     */
    func voiceSaved()  -> Double?
    
    /**
     * Unpaired on the phone: what was sent is forgotten (pairing again sends it all; the computer
     * knows what it already has). What came back revised stays revised.
     */
    func forgetComputer() throws 
    
    /**
     * Pairs with the computer of the QR's `uri`. `extra` are more addresses to try (the ones
     * Bonjour found), after the code's own. Returns the computer, to remember.
     */
    func pair(uri: String, extra: [String], privateKey: Data, phoneName: String) throws  -> Computer
    
    /**
     * Sends the computer every finished meeting it doesn't have yet (with its audio, resuming a
     * cut one), then picks up what it has revised. One sync at a time.
     * `keep_audio` false (Configuració › Desa l'àudio al telèfon): a meeting's audio is deleted
     * from the phone once the computer has stored it whole and checked.
     */
    func sync(candidates: [String], privateKey: Data, computerKey: Data, phoneName: String, keepAudio: Bool) throws  -> SyncReport
    
    /**
     * Finished meetings the computer doesn't have yet.
     */
    func unsentCount() throws  -> UInt32
    
}
