#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMurmur: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Murmur

    public static func lift(_ handle: UInt64) throws -> Murmur {
        return Murmur(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Murmur) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Murmur {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Murmur, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeMurmur_lift(_ handle: UInt64) throws -> Murmur {
    return try FfiConverterTypeMurmur.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeMurmur_lower(_ value: Murmur) -> UInt64 {
    return FfiConverterTypeMurmur.lower(value)
}




/**
 * The computer this phone is paired with.
 */
public struct Computer: Equatable, Hashable {
    public var name: String
    /**
     * Its public key (not secret): to know it again.
     */
    public var key: Data
    /**
     * The address that answered, to try first next time.
     */
    public var address: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(name: String, 
        /**
         * Its public key (not secret): to know it again.
         */key: Data, 
        /**
         * The address that answered, to try first next time.
         */address: String) {
        self.name = name
        self.key = key
        self.address = address
    }

    

    
}

