        /**
         * The computer has revised it (Whisper, speakers, summary).
         */revised: Bool, 
        /**
         * Recorded on the computer and sent here, text only: no audio on the phone.
         */fromComputer: Bool) {
        self.id = id
        self.title = title
        self.createdAt = createdAt
        self.duration = duration
        self.status = status
        self.tags = tags
        self.lastLine = lastLine
