@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMurmurError: FfiConverterRustBuffer {
    typealias SwiftType = MurmurError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MurmurError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Failed(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .NotACode
        case 3: return .CodeExpired
        case 4: return .Unreachable
        case 5: return .NotPaired
        case 6: return .Busy

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MurmurError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Failed(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)
            
        
        case .NotACode:
            writeInt(&buf, Int32(2))
        
        
        case .CodeExpired:
            writeInt(&buf, Int32(3))
        
        
        case .Unreachable:
            writeInt(&buf, Int32(4))
        
        
        case .NotPaired:
            writeInt(&buf, Int32(5))
        
        
        case .Busy:
            writeInt(&buf, Int32(6))
        
        }
    }
}


